780	        placeholders = ",".join("?" for _ in id_chunk)
781	        existing.update(
782	            row[0]
783	            for row in database.execute(
784	                "SELECT id FROM clients WHERE id IN (%s)" % placeholders, id_chunk
785	            )
786	        )
787	    missing = [cid for cid in ids if cid not in existing]
788	    if missing:
789	        raise BatchUpdateError("找不到对应客户，编号：%s" % "、".join(str(c) for c in missing))
790	
791	    # 每条 UPDATE 还要为每个修改字段绑定一个赋值参数，编号分块需相应留出位置。
792	    id_chunk_size = max(1, variable_limit - len(actions))
793	    assignments = ", ".join("%s = ?" % field_name for field_name in actions)
794	    values = list(actions.values())
795	    try:
796	        for id_chunk in _chunked(ids, id_chunk_size):
797	            placeholders = ",".join("?" for _ in id_chunk)
798	            database.execute(
799	                "UPDATE clients SET %s WHERE id IN (%s)" % (assignments, placeholders),
800	                values + id_chunk,
801	            )
802	        database.commit()
803	    except sqlite3.DatabaseError:
804	        database.rollback()
805	        raise BatchUpdateError("保存失败：数据库错误，本次修改未生效")
