928	def import_clients(database, text):
929	    """执行导入，返回响应字典；文件级错误抛 FileError。"""
930	    header, data_rows = parse_csv(text)
931	    headers = [h.strip() for h in header]
932	
933	    seen = set()
934	    duplicates = []
935	    for h in headers:
936	        if h in seen and h not in duplicates:
937	            duplicates.append(h)
938	        seen.add(h)
939	    if duplicates:
940	        raise FileError("表头重复：%s" % "、".join(repr(h) for h in duplicates))
941	    unknown = [h for h in headers if h not in ALL_COLUMNS]
942	    if unknown:
943	        raise FileError("出现未知列：%s" % "、".join(repr(h) for h in unknown))
